const ROOT = "src/app";
const URL_SCHEME = /^[A-Za-z][A-Za-z0-9+.-]*:/;

export function isAllowedPath(value) {
  if (typeof value !== "string" || value.length === 0) return false;
  if (value.includes("\\") || value.includes("%") || value.includes("\0")) return false;
  if (value.startsWith("/") || URL_SCHEME.test(value)) return false;

  const segments = value.split("/");
  if (segments.some((segment) => segment === "" || segment === "." || segment === "..")) {
    return false;
  }

  return value.startsWith(ROOT);
}

import assert from "node:assert/strict";

const modulePath = process.argv[2];
if (typeof modulePath !== "string") {
  throw new Error("usage: node test.mjs ./starter.mjs");
}

const { isAllowedPath } = await import(modulePath);
const cases = [
  ["allowed descendant", "src/app/config.json", true],
  ["allowed nested descendant", "src/app/lib/index.js", true],
  ["allowed directory itself", "src/app", true],
  ["sibling-prefix changed input", "src/application/config.json", false],
  ["unrelated path", "src/api/config.json", false],
  ["null input", null, false],
  ["structurally invalid input", { path: "src/app/config.json" }, false],
  ["empty string", "", false],
  ["traversal escapes root", "src/app/../../secret", false],
  ["parent segment changes directory", "src/app/../other", false],
  ["current-directory segment", "src/app/./config.json", false],
  ["absolute path", "/src/app/config.json", false],
  ["backslash separator", "src\\app\\config.json", false],
  ["URL input", "https://example.test/src/app/config.json", false],
  ["percent-encoded path", "src/app%2Fsecret.txt", false]
];

const failures = [];
for (const [name, input, expected] of cases) {
  const actual = isAllowedPath(input);
  try {
    assert.equal(actual, expected);
  } catch {
    failures.push(`${name}: expected ${expected}, received ${actual}`);
  }
}

if (failures.length > 0) {
  console.error(`FAIL ${failures.length}/${cases.length}`);
  for (const failure of failures) console.error(failure);
  console.error("Cause: the authorization predicate crosses the src/app directory boundary.");
  process.exitCode = 1;
} else {
  console.log(`PASS ${cases.length}/${cases.length}`);
}

const ROOT = "src/app";
const URL_SCHEME = /^[A-Za-z][A-Za-z0-9+.-]*:/;

export function isAllowedPath(value) {
  if (typeof value !== "string" || value.length === 0) return false;
  if (value.includes("\\") || value.includes("%") || value.includes("\0")) return false;
  if (value.startsWith("/") || URL_SCHEME.test(value)) return false;

  const segments = value.split("/");
  if (segments.some((segment) => segment === "" || segment === "." || segment === "..")) {
    return false;
  }

  return value === ROOT || value.startsWith(`${ROOT}/`);
}
